   311	    // Make sure we have a clean Typing indicator before subscribing to typing events
   312	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   313	
   314	    const pusherChannelName = getReportChannelName(reportID);
   315	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   316	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
