   310	
   311	    // Make sure we have a clean Typing indicator before subscribing to typing events
   312	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   313	
   314	    const pusherChannelName = getReportChannelName(reportID);
   315	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   316	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
   317	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   318	        // since personal details are keyed by accountID.
   319	        const normalizedTypingStatus = getNormalizedStatus(typingStatus);
   320	        const accountIDOrLogin = Object.keys(normalizedTypingStatus)[0];
   321	
   322	        if (!accountIDOrLogin) {
   323	            return;
   324	        }
   325	
   326	        // Don't show the typing indicator if the user is typing on another platform
