   336	        // Wait for 1.5s of no additional typing events before setting the status back to false.
   337	        typingWatchTimers[reportUserIdentifier] = setTimeout(() => {
   338	            const typingStoppedStatus: ReportUserIsTyping = {};
   339	            typingStoppedStatus[accountIDOrLogin] = false;
   340	            Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, typingStoppedStatus);
   341	            delete typingWatchTimers[reportUserIdentifier];
   342	        }, 1500);
   343	    }).catch((error) => {
   344	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
