    12	 * Download the latest app version from the server, and if it is different than the current one,
    13	 * then refresh. If the page is visibile, prompt the user to refresh.
    14	 */
    15	function webUpdate() {
    16	    fetch('/version.json', {cache: 'no-cache'})
    17	        .then((response) => response.json())
    18	        .then(({version}) => {
    19	            if (version === pkg.version) {
    20	                return;
    21	            }
    22	
    23	            if (!Visibility.isVisible()) {
    24	                // Page is hidden, refresh immediately
    25	                window.location.reload();
    26	                return;
    27	            }
    28	
    29	            // Prompt user to refresh the page
    30	            if (window.confirm('Refresh the page to get the latest updates!')) {
    31	                window.location.reload();
    32	            }
    33	        });
    34	}
    35	
    36	/**
    37	 * Create an object whose shape reflects the callbacks used in checkForUpdates.
    38	 */
    39	const webUpdater = (): PlatformSpecificUpdater => ({
    40	    init: () => {
    41	        // We want to check for updates and refresh the page if necessary when the app is backgrounded.
    42	        // That way, it will auto-update silently when they minimize the page,
    43	        // and we don't bug the user any more than necessary :)
    44	        window.addEventListener('visibilitychange', () => {
    45	            if (Visibility.isVisible()) {
    46	                return;
    47	            }
    48	
    49	            webUpdate();
    50	        });
    51	    },
    52	    update: () => webUpdate(),
    53	});
    54	
    55	export default function () {
    56	    AppRegistry.runApplication(Config.APP_NAME, {
    57	        rootTag: document.getElementById('root'),
    58	        mode: 'legacy',
    59	    });
    60	
    61	    // When app loads, get current version (production only)
    62	    if (Config.IS_IN_PRODUCTION) {
    63	        checkForUpdates(webUpdater());
    64	    }
    65	
    66	    // Start current date updater
    67	    DateUtils.startCurrentDateUpdater();
    68	}
